 "content": "def transform(grid):
    """Shift the grid down one row, filling the top row with the background."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [[background] * w for _ in range(h)]
    for r in range(h - 1):
        out[r + 1] = list(grid[r])
    return out
